<?php
require_once __DIR__ . '/../config/security.php';
start_secure_session();
require_once __DIR__ . '/../config/database.php';
require_portal_role($conn, 'dentist', false);

start_secure_session();if(($_SESSION['role']??'')!=='dentist'){header('Location: ../auth/login.php');exit;}require_once '../config/database.php';$patientId=(int)($_GET['id']??0);if($patientId<1){header('Location: patients.php');exit;}
$st=$conn->prepare("SELECT id,first_name,last_name,email,status,created_at FROM users WHERE id=? AND role='patient' LIMIT 1");$st->bind_param('i',$patientId);$st->execute();$patient=$st->get_result()->fetch_assoc();$st->close();if(!$patient){header('Location: patients.php');exit;}$fullName=$patient['first_name'].' '.$patient['last_name'];
$reported=[];$st=$conn->prepare("SELECT tooth_number,concern_type,updated_at FROM patient_tooth_reports WHERE patient_id=? AND concern_type IN ('Healthy','Caries','Filled','Missing','Fractured') ORDER BY updated_at DESC,id DESC");$st->bind_param('i',$patientId);$st->execute();$r=$st->get_result();while($x=$r->fetch_assoc()){if(!isset($reported[$x['tooth_number']]))$reported[$x['tooth_number']]=$x['concern_type'];}$st->close();
$latestChart=0;$st=$conn->prepare("SELECT id FROM dental_charts WHERE patient_id=? ORDER BY COALESCE(chart_date,DATE(created_at)) DESC,id DESC LIMIT 1");$st->bind_param('i',$patientId);$st->execute();$latestChart=(int)($st->get_result()->fetch_assoc()['id']??0);$st->close();
$permanent=['18','17','16','15','14','13','12','11','21','22','23','24','25','26','27','28','48','47','46','45','44','43','42','41','31','32','33','34','35','36','37','38'];
// Dental records: whatever the dentist saves here appears in the patient's Dental Records, and the patient is notified.
require_once __DIR__.'/../includes/patient_records.php';
$recordMsg='';$recordType='success';$uid=(int)$_SESSION['user_id'];
$services=[];$sr=$conn->query("SELECT name FROM services WHERE is_active=1 ORDER BY id");if($sr)while($x=$sr->fetch_assoc())$services[]=$x['name'];
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='add_record'){
    $recDate=(string)($_POST['record_date']??'');$proc=trim((string)($_POST['procedure_name']??''));$diag=trim((string)($_POST['diagnosis']??''));$recNotes=trim((string)($_POST['notes']??''));$teethIn=(string)($_POST['tooth_number']??'');
    $dateOk=preg_match('/^\d{4}-\d{2}-\d{2}$/',$recDate)&&strtotime($recDate)!==false&&$recDate<=date('Y-m-d');
    if(!$dateOk){$recordMsg='Choose a valid record date (today or earlier).';$recordType='error';}
    elseif($proc===''||mb_strlen($proc)>150){$recordMsg='Enter the procedure or service (up to 150 characters).';$recordType='error';}
    elseif(mb_strlen($diag)>255||mb_strlen($recNotes)>5000){$recordMsg='The diagnosis or notes are too long.';$recordType='error';}
    elseif(trim($teethIn)!==''&&sd_clean_tooth_list($teethIn)===''){$recordMsg='Enter tooth numbers like 16, 26 (FDI numbering).';$recordType='error';}
    else{
        $newRecord=sd_share_record_with_patient($conn,['patient_id'=>$patientId,'dentist_id'=>$uid,'record_date'=>$recDate,'procedure_name'=>$proc,'diagnosis'=>$diag,'notes'=>$recNotes,'tooth_number'=>$teethIn,'source'=>'manual']);
        log_activity($conn,$uid,'Added dental record','Dental Records','Record #'.$newRecord.' · patient #'.$patientId);
        header('Location: patient_view.php?id='.$patientId.'&record_saved=1#records');exit;
    }
}
if(isset($_GET['record_saved'])){$recordMsg='Dental record saved. The patient can now see it in Dental Records and was notified.';}
$records=[];$st=$conn->prepare("SELECT id,record_date,procedure_name,diagnosis,dentist_name,notes,tooth_number,source FROM dental_records WHERE patient_id=? ORDER BY record_date DESC,id DESC LIMIT 50");$st->bind_param('i',$patientId);$st->execute();$records=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
$sourceLabels=['manual'=>'Procedure','chart'=>'Examination chart','visit'=>'Completed visit','odontogram'=>'3D odontogram','plan'=>'Treatment plan'];
require '../includes/ui.php';ui_header('Patient Care','dentist');ui_sidebar('dentist','patients.php');?>
<div class="page-head patient-care-head"><div><div class="eyebrow">PATIENT CARE</div><h1><?=e($fullName)?></h1><div class="muted">Review patient information, self-reported dental conditions, and clinical chart records.</div></div><a class="btn btn-secondary" href="patients.php">All Patients</a></div>
<section class="card patient-profile-card"><div class="patient-profile-identity"><span class="patient-initial large"><?=e(strtoupper(substr($patient['first_name'],0,1)))?></span><div><h2><?=e($fullName)?></h2><p class="muted">Patient ID: <?=e($patient['id'])?></p></div></div><div class="patient-details"><div><small>Email</small><b><?=e($patient['email'])?></b></div><div><small>Account Status</small><b><span class="badge status-<?=e(strtolower($patient['status']))?>"><?=e(ucfirst($patient['status']))?></span></b></div><div><small>Registered</small><b><?=e(date('M d, Y',strtotime($patient['created_at'])))?></b></div></div></section>
<section class="card"><div class="card-heading"><div><h2>Patient-Reported Dental Condition Map</h2><p class="muted">These marks were selected by the patient and should be clinically confirmed by the dentist.</p></div><span class="badge"><?=count($reported)?> marked</span></div><div class="condition-summary"><span><i class="condition-dot healthy"></i>Healthy</span><span><i class="condition-dot caries"></i>Caries</span><span><i class="condition-dot filled"></i>Filled</span><span><i class="condition-dot missing"></i>Missing</span><span><i class="condition-dot fractured"></i>Fractured</span></div><div class="dental-arches readonly"><div class="arch-label">Upper Arch</div><div class="tooth-arch"><?php foreach(array_slice($permanent,0,16) as $tooth):?><div class="chart-tooth" data-mark="<?=e($reported[$tooth]??'')?>"><span class="tooth-crown"></span><b><?=$tooth?></b></div><?php endforeach;?></div><div class="tooth-arch lower"><?php foreach(array_slice($permanent,16) as $tooth):?><div class="chart-tooth" data-mark="<?=e($reported[$tooth]??'')?>"><span class="tooth-crown"></span><b><?=$tooth?></b></div><?php endforeach;?></div><div class="arch-label">Lower Arch</div></div></section>
<section class="card"><div class="card-heading"><div><h2>Dental Care Management</h2><p class="muted">Open this patient's clinical chart records or create a new 3D dental chart.</p></div></div><div class="care-grid"><a class="care-card" href="chart_editor.php?patient_id=<?=$patientId?>"><span><h3>Create Chart</h3><p>Record examination details and mark teeth in the interactive 3D model.</p></span></a><a class="care-card" href="charts.php?patient_id=<?=$patientId?>"><span><h3>Chart Records</h3><p>View, print, edit, or delete this patient's saved charts.</p></span></a><a class="care-card" href="treatment_plans.php?patient_id=<?=$patientId?>"><span><h3>Treatment Plans</h3><p>Create and manage recommended care.</p></span></a><?php if($latestChart):?><a class="care-card" href="chart_view.php?id=<?=$latestChart?>"><span><h3>Latest Chart</h3><p>Open the most recent clinical chart for this patient.</p></span></a><?php endif;?><a class="care-card" href="odontogram.php?patient_id=<?=$patientId?>"><span><h3>3D Odontogram</h3><p>Record tooth conditions and treatments on the 3D model.</p></span></a></div></section>
<section class="card" id="records"><div class="card-heading"><div><h2>Dental Records</h2><p class="muted">Everything saved here is shared with the patient in their Dental Records and Treatment History, and the patient gets a notification.</p></div><span class="badge"><?=count($records)?> record<?=count($records)===1?'':'s'?></span></div>
<?php if($recordMsg)flash($recordType,$recordMsg);?>
<form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_record">
<div class="field"><label for="recDate">Record date *</label><input type="date" id="recDate" name="record_date" max="<?=date('Y-m-d')?>" value="<?=e($_POST['record_date']??date('Y-m-d'))?>" required></div>
<div class="field"><label for="recProc">Procedure / service *</label><input id="recProc" name="procedure_name" maxlength="150" list="recServices" value="<?=e($_POST['procedure_name']??'')?>" placeholder="e.g. Tooth Extraction" required><datalist id="recServices"><?php foreach($services as $sv):?><option value="<?=e($sv)?>"><?php endforeach;?></datalist></div>
<div class="field"><label for="recTeeth">Tooth number(s)</label><input id="recTeeth" name="tooth_number" maxlength="160" value="<?=e($_POST['tooth_number']??'')?>" placeholder="e.g. 36 or 16, 26"></div>
<div class="field"><label for="recDiag">Diagnosis / findings</label><input id="recDiag" name="diagnosis" maxlength="255" value="<?=e($_POST['diagnosis']??'')?>" placeholder="e.g. Deep caries"></div>
<div class="field full"><label for="recNotes">Notes / instructions for the patient</label><textarea id="recNotes" name="notes" maxlength="5000" placeholder="Treatment done, medicines, after-care instructions"><?=e($_POST['notes']??'')?></textarea></div>
<div class="actions full"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Save &amp; Send to Patient</button></div></form>
<div class="table-wrap"><table class="record-table"><thead><tr><th>Date</th><th>Record</th><th>Teeth</th><th>Diagnosis</th><th>Recorded by</th></tr></thead><tbody>
<?php if(!$records):?><tr><td colspan="5" class="empty">No dental records yet.</td></tr><?php endif;?>
<?php foreach($records as $r):?><tr><td data-label="Date"><?=e(date('M d, Y',strtotime($r['record_date'])))?></td><td data-label="Record"><b><?=e($r['procedure_name'])?></b><br><small class="muted"><?=e($sourceLabels[$r['source']??'manual']??'Record')?></small><?php if(trim((string)$r['notes'])!==''):?><br><small><?=nl2br(e(mb_strimwidth((string)$r['notes'],0,220,'…')))?></small><?php endif;?></td><td data-label="Teeth"><?=e($r['tooth_number']?:'—')?></td><td data-label="Diagnosis"><?=e($r['diagnosis']?:'—')?></td><td data-label="Recorded by"><?=e($r['dentist_name']?:'Clinic staff')?></td></tr><?php endforeach;?>
</tbody></table></div></section>
<?php ui_footer();?>
